import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Applicazione dei criteri di congruenza fra triangoli ai problemi geometrici","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fd/fdae.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fd/fdae.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fd/fdae.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="applicazione-dei-criteri-di-congruenza-fra-triangoli-ai-problemi-geometrici" tabindex="-1">Applicazione dei criteri di congruenza fra triangoli ai problemi geometrici <a class="header-anchor" href="#applicazione-dei-criteri-di-congruenza-fra-triangoli-ai-problemi-geometrici" aria-label="Permalink to “Applicazione dei criteri di congruenza fra triangoli ai problemi geometrici”">​</a></h1><p>Ora che conosciamo i criteri che uso ne possiamo fare? Questa domanda ci porta al metodo di soluzione dei problemi in geometria: corrisponde un po&#39; a quello che ho mostrato in algebra però con alcune differenze.</p><p>Intanto c&#39;è da dire che i criteri mi permettono di risolvere la metà dei problemi relativi alle dimostrazioni di geometria:</p><p>Risolvere un problema geometrico significa dimostrare che sono congruenti dei lati o degli angoli; quindi dovrai individuare dei triangoli che contengano quei lati o quegli angoli e dovrai dimostrare che sono congruenti per il primo, il secondo, il terzo criterio.</p><p>Il metodo è sempre quello: parto dalla tesi, individuo due triangoli che contengano gli elementi della tesi e vedo se posso applicare un criterio per dire che sono congruenti; se mi manca qualcosa considero altri due triangoli che contengano quel qualcosa e vedo se posso applicare un criterio (di solito non si va oltre due applicazioni ripetute). Quando ho trovato ribalto il ragionamento e scrivo cominciando dall&#39;ultimo ed andando verso il primo ragionamento (dalle ipotesi vado verso la tesi) sempre col seguente schema:</p><blockquote><p class="text-blue">[Considero i triangoli <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>F</mi><mi>G</mi><mi>H</mi></mrow><annotation encoding="application/x-tex">FGH</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mord mathnormal">G</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi><mi>M</mi><mi>N</mi></mrow><annotation encoding="application/x-tex">LMN</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span>]</p><p class="text-blue">[Essi hanno (scrivo quello che hanno di congruente e perché)]</p><p class="text-blue">[<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>lato</mtext><mo>=</mo><mtext>lato</mtext></mrow><annotation encoding="application/x-tex">\\text{lato} = \\text{lato}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">lato</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">lato</span></span></span></span></span> perché ...(ipotesi, costruzione, già dimostrato...)]</p><p class="text-blue">[<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>lato</mtext><mo>=</mo><mtext>lato</mtext></mrow><annotation encoding="application/x-tex">\\text{lato} = \\text{lato}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">lato</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">lato</span></span></span></span></span> perché ...(ipotesi, costruzione, già dimostrato...)]</p><p class="text-blue">[<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>angolo</mtext><mo>=</mo><mtext>angolo</mtext></mrow><annotation encoding="application/x-tex">\\text{angolo} = \\text{angolo}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">angolo</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">angolo</span></span></span></span></span> perché ...(ipotesi, costruzione, già dimostrato...)]</p><p class="text-blue">[Quindi i due triangoli sono congruenti per il primo (o secondo o terzo) criterio ed in particolare avranno congruenti (quello che mi interessa o per continuare o perché è la tesi)]</p></blockquote><p>Vediamo alcuni esempi che chiariranno meglio il metodo:</p><p>I. <a href="./fdae1.html">Esempio</a> II. <a href="./fdae2.html">Esempio</a> III. <a href="./fdae3.html">Esempio</a></p><p>Naturalmente ancora, conoscendo solamente i tre criteri, le dimostrazioni sono semplici: diventeranno più complicate man mano che aggiungerai nuove figure geometriche e nuovi teoremi, ma il principio di base è sempre lo stesso.</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};